// CSD_RATIONALE_BEGIN
// Strategy: Clean single-span constrained CSD for GSM-symbolic arithmetic.
//
// Key insights from diagnostics:
// 1. Syntax rate is only 55.1% - "malformed_constrained_content" is the top failure (22/49)
// 2. Many examples have unterminated spans (40/49 unterminated in last attempt)
// 3. The model generates multiple partial spans instead of one clean final answer
// 4. We need ONE clean constrained span with valid arithmetic expression at the end
//
// NEW APPROACH:
// 1. Generate free reasoning until EOS or budget limit (no reactive span watching)
// 2. At the end of free reasoning, force ONE constrained span open via OpenConstrainedSpan
// 3. Hard-constrain with AdaptiveConstrainedStep until parser.IsCompletePrefix
// 4. Immediately close with CloseConstrainedSpan
// 5. Use RollbackConstrainedToComplete if EOS arrives before completion
// 6. Reserve 30 steps at end of budget for the constrained span
//
// Critical change: During free generation, IGNORE any "<<" tokens the model emits
// (don't call EnterObservedConstrainedSpan). We only want ONE final controlled span.
// The multiple-span problem was causing malformed content in delimiters.
//
// Also: keep free generation shorter (stop at 80% of budget) and then force the span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   - Free phase: insideConstrainedOut is always false, so the implication is vacuous.
//     We do NOT flip to true on any "<<" during free phase.
//   - OpenConstrainedSpan: sets insideConstrainedOut:=true, currentConstrainedOut:=[].
//     [] is valid by precondition parser.IsValidPrefix([]).
//   - Constrained step (append): AdaptiveConstrainedStep returns EOS or a parser-valid token.
//     AppendConstrainedToken preserves parser.IsValidPrefix by contract.
//   - Constrained step (EOS/rollback): RollbackConstrainedToComplete returns complete prefix or [].
//     If empty (not complete): set insideConstrainedOut:=false, [] (vacuous).
//     If non-empty complete: insideConstrainedOut stays true, prefix is valid.
//   - CloseConstrainedSpan: sets insideConstrainedOut:=false (implication vacuous), clears current to [].
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   - Free unconstrained: steps+1, generated grows by at most 1 (non-EOS).
//   - OpenConstrainedSpan: steps+1, generated grows by exactly 1 ("<<").
//   - CloseConstrainedSpan: steps+1, generated grows by at most 1 (">>").
//   - Constrained step (append): steps+1, generated grows by exactly 1.
//   - Constrained step (EOS/rollback): steps+1, RollbackConstrainedToComplete shrinks/preserves generated.
//   Each branch increments steps by exactly 1.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve the math word problem step by step. At the very end, write ONLY the final arithmetic expression inside << >> delimiters with no text outside. Use only numbers, +, -, *, /, (, ) characters inside the delimiters. Do not open << >> until you have the final answer.");

var steps: nat := 0;
// Reserve budget for constrained span: need enough for expression + close
var constrainedReserve: nat := if maxSteps >= 50 then 40 else if maxSteps >= 20 then maxSteps / 2 else maxSteps;
var freePhaseLimit: nat := if maxSteps > constrainedReserve then maxSteps - constrainedReserve else 0;
var forcedOpen: bool := insideConstrained; // Already in constrained if pre-entering

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Check if we should force open a constrained span
    if steps >= freePhaseLimit && steps + 3 <= maxSteps {
      // Time to open the constrained span for the final answer
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      forcedOpen := true;
      steps := steps + 1;
    } else {
      // Free generation - ignore model "<<" tokens, just accumulate reasoning
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        // Model wants to stop - if we have budget, force open the constrained span now
        if steps + 3 <= maxSteps {
          var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
          generated := og;
          insideConstrainedOut := oi;
          currentConstrainedOut := oc;
          forcedOpen := true;
          steps := steps + 1;
        } else {
          break;
        }
      } else {
        // Append the token but do NOT enter constrained mode even if it's "<<"
        generated := generated + [next];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    // Span is complete - close it immediately
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    // After closing, stop - we have our answer
    break;
  } else {
    // Inside constrained span, not yet complete - generate next parser-valid token
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken);
    steps := steps + 1;
    if next == eosToken {
      // EOS inside span: rollback to complete prefix if possible
      var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
      generated := rg;
      currentConstrainedOut := rc;
      if parser.IsCompletePrefix(currentConstrainedOut) && steps + 1 <= maxSteps {
        // Can close the span
        var cg2, ci2, cc2 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg2;
        insideConstrainedOut := ci2;
        currentConstrainedOut := cc2;
        steps := steps + 1;
      } else {
        // Can't close - just exit constrained mode
        insideConstrainedOut := false;
        currentConstrainedOut := [];
      }
      break;
    } else {
      // Append valid token
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// If we exit the loop still inside a constrained span, try to close it
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Rollback to complete and close if possible
    var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
    generated := rg;
    currentConstrainedOut := rc;
    if parser.IsCompletePrefix(currentConstrainedOut) && steps + 1 <= maxSteps {
      var cg2, ci2, cc2 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg2;
      insideConstrainedOut := ci2;
      currentConstrainedOut := cc2;
      steps := steps + 1;
    } else {
      insideConstrainedOut := false;
      currentConstrainedOut := [];
    }
  }
}

cost := steps;

